package com.bank.hr.service;

import com.bank.hr.dto.DeptHeadcount;
import com.bank.hr.model.Department;
import com.bank.hr.model.Employee;
import com.bank.hr.repository.HrRepository;

import java.util.*;
import java.util.logging.Logger;

public class HeadcountService {
    private static final Logger log = Logger.getLogger(HeadcountService.class.getName());
    private final HrRepository repo;
    public HeadcountService(HrRepository repo) { this.repo = repo; }

    // LEFT JOIN from department to employees, COUNT(e.emp_id) so empty depts show 0.
    public List<DeptHeadcount> countPerDepartment() {
        Map<Integer, Long> counts = new HashMap<>();
        for (Employee e : repo.allEmployees()) {
            counts.merge(e.getDeptId(), 1L, Long::sum); // COUNT per dept_id
        }
        List<DeptHeadcount> result = new ArrayList<>();
        for (Department d : repo.allDepartments()) {
            long c = counts.getOrDefault(d.getDeptId(), 0L); // 0 for Crypto Desk
            result.add(new DeptHeadcount(d.getDeptName(), c));
        }
        result.sort((a, b) -> Long.compare(b.getCount(), a.getCount())); // ORDER BY count DESC
        log.info(() -> "Computed headcount for " + result.size() + " departments");
        return result;
    }
}
