package com.bank.hr;

import com.bank.hr.dto.DeptHeadcount;
import com.bank.hr.repository.HrRepository;
import com.bank.hr.service.HeadcountService;

public class HrApplication {
    public static void main(String[] args) {
        HeadcountService service = new HeadcountService(new HrRepository());
        System.out.println("DEPARTMENT          HEADCOUNT");
        for (DeptHeadcount h : service.countPerDepartment()) {
            System.out.printf("%-18s  %d%n", h.getDeptName(), h.getCount());
        }
    }
}
